import CryptoKit
import Sodium
import Foundation
import Security

/// The cryptographic primitives from API contract section 1, as pure functions over
/// bytes so they can be checked against the shared test vectors
/// (vectors/v1.json, generated by Leave's server code, the same file every implementation is held to).
/// Nothing here touches the Keychain or the network; LeaveCrypto.swift does that.
///
/// Wire formats: AES-256-GCM is `nonce(12) ‖ ciphertext ‖ tag(16)`; HPKE is
/// `enc(65) ‖ ciphertext ‖ tag`; every string in the protocol is UTF-8 and every
/// binary value crossing an API is base64url without padding.
enum LeaveCryptoCore {
  enum Failure: Error, LocalizedError {
    case badKeyLength
    case badWire
    case badPublicKey
    case scalarOutOfRange
    case rsa(String)

    var errorDescription: String? {
      switch self {
      case .badKeyLength: return "Key is not 32 bytes."
      case .badWire: return "Ciphertext is malformed."
      case .badPublicKey: return "Public key is malformed."
      case .scalarOutOfRange: return "Derived scalar is out of range."
      case .rsa(let m): return m
      }
    }
  }

  // MARK: - Record encryption (recordAead)

  static func aad(_ recordType: String, _ recordId: String) -> Data {
    Data("leave:v1:\(recordType):\(recordId)".utf8)
  }

  /// AES-256-GCM seal. A nil nonce draws a random one (production); the vectors pass theirs.
  static func seal(key: Data, plaintext: Data, aad: Data, nonce: Data? = nil) throws -> Data {
    guard key.count == 32 else { throw Failure.badKeyLength }
    let n = try nonce.map { try AES.GCM.Nonce(data: $0) } ?? AES.GCM.Nonce()
    let box = try AES.GCM.seal(plaintext, using: SymmetricKey(data: key), nonce: n, authenticating: aad)
    return Data(n) + box.ciphertext + box.tag
  }

  static func open(key: Data, wire: Data, aad: Data) throws -> Data {
    guard key.count == 32 else { throw Failure.badKeyLength }
    guard wire.count >= 12 + 16 else { throw Failure.badWire }
    let nonce = try AES.GCM.Nonce(data: wire.prefix(12))
    let tag = wire.suffix(16)
    let ciphertext = wire.dropFirst(12).dropLast(16)
    let box = try AES.GCM.SealedBox(nonce: nonce, ciphertext: ciphertext, tag: tag)
    return try AES.GCM.open(box, using: SymmetricKey(data: key), authenticating: aad)
  }

  // MARK: - Share wrap of a DEK (shareWrap)

  static func wrapKey(share: Data, recordId: String) -> Data {
    let k = HKDF<SHA256>.deriveKey(
      inputKeyMaterial: SymmetricKey(data: share),
      salt: Data(recordId.utf8),
      info: Data("leave:v1:dek-wrap".utf8),
      outputByteCount: 32
    )
    return k.withUnsafeBytes { Data($0) }
  }

  static func shareWrap(share: Data, recordType: String, recordId: String, dek: Data, nonce: Data? = nil) throws -> Data {
    try seal(key: wrapKey(share: share, recordId: recordId), plaintext: dek, aad: aad(recordType, recordId), nonce: nonce)
  }

  static func shareUnwrap(share: Data, recordType: String, recordId: String, wire: Data) throws -> Data {
    try open(key: wrapKey(share: share, recordId: recordId), wire: wire, aad: aad(recordType, recordId))
  }

  // MARK: - Account key (accountKey): rejection-sampled P-256 scalar

  /// P-256 group order n, big-endian.
  private static let p256Order = Data([
    0xff, 0xff, 0xff, 0xff, 0x00, 0x00, 0x00, 0x00, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
    0xbc, 0xe6, 0xfa, 0xad, 0xa7, 0x17, 0x9e, 0x84, 0xf3, 0xb9, 0xca, 0xc2, 0xfc, 0x63, 0x25, 0x51,
  ])

  /// 1 ≤ scalar ≤ n − 1, compared as big-endian bytes; no modular reduction.
  static func scalarInRange(_ s: Data) -> Bool {
    guard s.count == 32 else { return false }
    if s.allSatisfy({ $0 == 0 }) { return false }
    for (a, b) in zip(s, p256Order) {
      if a < b { return true }
      if a > b { return false }
    }
    return false // equal to n
  }

  static func accountScalar(share: Data, accountId: String) -> Data {
    var counter = 0
    while true {
      let candidate = HKDF<SHA256>.deriveKey(
        inputKeyMaterial: SymmetricKey(data: share),
        salt: Data("leave:v1:account-key".utf8),
        info: Data("\(accountId):\(counter)".utf8),
        outputByteCount: 32
      ).withUnsafeBytes { Data($0) }
      if scalarInRange(candidate) { return candidate }
      counter += 1
    }
  }

  static func accountSigningKey(share: Data, accountId: String) throws -> P256.Signing.PrivateKey {
    try P256.Signing.PrivateKey(rawRepresentation: accountScalar(share: share, accountId: accountId))
  }

  static func accountAgreementKey(share: Data, accountId: String) throws -> P256.KeyAgreement.PrivateKey {
    try P256.KeyAgreement.PrivateKey(rawRepresentation: accountScalar(share: share, accountId: accountId))
  }

  // MARK: - HPKE: DHKEM(P-256, HKDF-SHA256), HKDF-SHA256, AES-256-GCM, base mode

  static let hpkeSuite = HPKE.Ciphersuite.P256_SHA256_AES_GCM_256

  static func hpkeSeal(recipientSpki: Data, info: String, plaintext: Data) throws -> Data {
    let recipient = try P256.KeyAgreement.PublicKey(derRepresentation: recipientSpki)
    var sender = try HPKE.Sender(recipientKey: recipient, ciphersuite: hpkeSuite, info: Data(info.utf8))
    let ct = try sender.seal(plaintext)
    return sender.encapsulatedKey + ct
  }

  static func hpkeOpen(recipientKey: P256.KeyAgreement.PrivateKey, info: String, wire: Data) throws -> Data {
    guard wire.count > 65 + 16 else { throw Failure.badWire }
    let enc = wire.prefix(65)
    let ct = wire.dropFirst(65)
    var recipient = try HPKE.Recipient(privateKey: recipientKey, ciphersuite: hpkeSuite, info: Data(info.utf8), encapsulatedKey: enc)
    return try recipient.open(ct)
  }

  // MARK: - Session grant (grant)

  /// RSA-OAEP (SHA-256 hash and MGF1, empty label) of the 32-byte session key to the
  /// server's KMS public key (SPKI DER). Output is 384 bytes for RSA-3072.
  static func rsaSeal(serverSpki: Data, sessionKey: Data) throws -> Data {
    guard sessionKey.count == 32 else { throw Failure.badKeyLength }
    let attrs: [String: Any] = [
      kSecAttrKeyType as String: kSecAttrKeyTypeRSA,
      kSecAttrKeyClass as String: kSecAttrKeyClassPublic,
    ]
    var error: Unmanaged<CFError>?
    guard let key = SecKeyCreateWithData(stripSpkiHeaderIfRSA(serverSpki) as CFData, attrs as CFDictionary, &error) else {
      throw Failure.rsa("Server key is malformed: \(error?.takeRetainedValue().localizedDescription ?? "")")
    }
    guard let sealed = SecKeyCreateEncryptedData(key, .rsaEncryptionOAEPSHA256, sessionKey as CFData, &error) else {
      throw Failure.rsa("Could not seal the session key: \(error?.takeRetainedValue().localizedDescription ?? "")")
    }
    return sealed as Data
  }

  /// Test helper: the inverse with a PKCS#8 private key (only the vectors carry one).
  static func rsaOpen(privateKeyPkcs8: Data, sealed: Data) throws -> Data {
    let attrs: [String: Any] = [
      kSecAttrKeyType as String: kSecAttrKeyTypeRSA,
      kSecAttrKeyClass as String: kSecAttrKeyClassPrivate,
    ]
    var error: Unmanaged<CFError>?
    guard let key = SecKeyCreateWithData(stripPkcs8HeaderIfRSA(privateKeyPkcs8) as CFData, attrs as CFDictionary, &error) else {
      throw Failure.rsa("Private key is malformed: \(error?.takeRetainedValue().localizedDescription ?? "")")
    }
    guard let plain = SecKeyCreateDecryptedData(key, .rsaEncryptionOAEPSHA256, sealed as CFData, &error) else {
      throw Failure.rsa("Could not open the session key: \(error?.takeRetainedValue().localizedDescription ?? "")")
    }
    return plain as Data
  }

  static func grantAad(sessionId: String, recordId: String) -> Data {
    Data("leave:v1:grant:\(sessionId):\(recordId)".utf8)
  }

  static func sealDek(sessionKey: Data, sessionId: String, recordId: String, dek: Data, nonce: Data? = nil) throws -> Data {
    try seal(key: sessionKey, plaintext: dek, aad: grantAad(sessionId: sessionId, recordId: recordId), nonce: nonce)
  }

  // MARK: - Signatures (signatures)

  static func verify(spki: Data, message: Data, signature: Data) throws -> Bool {
    let key = try P256.Signing.PublicKey(derRepresentation: spki)
    let sig: P256.Signing.ECDSASignature
    if signature.count == 64 {
      sig = try P256.Signing.ECDSASignature(rawRepresentation: signature)
    } else {
      sig = try P256.Signing.ECDSASignature(derRepresentation: signature)
    }
    return key.isValidSignature(sig, for: message)
  }

  // MARK: - Hashing and encoding

  static func sha256Hex(_ data: Data) -> String {
    SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
  }

  // MARK: - Recovery code (API contract, "Recovery blob")

  /// Crockford base32: no I, L, O or U, so a code read aloud or copied by hand has no look-alikes.
  static let recoveryAlphabet = Array("0123456789ABCDEFGHJKMNPQRSTVWXYZ")
  static let recoveryCodeLength = 28

  /// 28 characters, 5 bits each (140 bits), from the system's random generator.
  static func newRecoveryCode() throws -> String {
    var bytes = [UInt8](repeating: 0, count: recoveryCodeLength)
    guard SecRandomCopyBytes(kSecRandomDefault, bytes.count, &bytes) == errSecSuccess else { throw Failure.badWire }
    return String(bytes.map { recoveryAlphabet[Int($0 & 0x1f)] })
  }

  /// What was typed, as the code itself: upper case, spaces and hyphens dropped, and the letters
  /// the alphabet leaves out read as the digits they are mistaken for (O as 0, I and L as 1).
  /// Nil when it isn't 28 characters of the alphabet.
  static func normalizeRecoveryCode(_ typed: String) -> String? {
    let mapped = typed.uppercased().compactMap { c -> Character? in
      switch c {
      case " ", "-", "\n", "\t": return nil
      case "O": return "0"
      case "I", "L": return "1"
      default: return c
      }
    }
    guard mapped.count == recoveryCodeLength, mapped.allSatisfy({ recoveryAlphabet.contains($0) }) else { return nil }
    return String(mapped)
  }

  /// "K7Q2 M9X4 T6W1 …": groups of four, as it is shown and written down.
  static func groupedRecoveryCode(_ code: String) -> String {
    stride(from: 0, to: code.count, by: 4).map { i in
      String(code[code.index(code.startIndex, offsetBy: i)..<code.index(code.startIndex, offsetBy: min(i + 4, code.count))])
    }.joined(separator: " ")
  }

  /// The key a recovery code locks the share with: Argon2id, 64 MiB, 3 passes, 1 lane, 32 bytes
  /// (the contract's parameters; RFC 9106's second recommended memory and passes). libsodium's
  /// crypto_pwhash, whose lane count is 1. It takes a few seconds; callers run it off the main thread.
  static func recoveryKey(code: String, salt: Data) throws -> Data {
    guard salt.count == 16,
          let key = Sodium().pwHash.hash(outputLength: 32, passwd: Array(code.utf8), salt: Array(salt), opsLimit: 3, memLimit: 64 * 1024 * 1024, alg: .Argon2ID13)
    else { throw Failure.badWire }
    return Data(key)
  }

  /// `0x01 ‖ salt(16) ‖ nonce(12) ‖ AES-256-GCM(share) ‖ tag(16)`, no associated data.
  static func sealRecovery(share: Data, code: String, salt: Data, nonce: Data) throws -> Data {
    guard share.count == 32, nonce.count == 12 else { throw Failure.badWire }
    let box = try AES.GCM.seal(share, using: SymmetricKey(data: try recoveryKey(code: code, salt: salt)), nonce: try AES.GCM.Nonce(data: nonce))
    return Data([0x01]) + salt + nonce + box.ciphertext + box.tag
  }

  /// The share inside a recovery blob. Throws when the code is wrong (the tag doesn't verify) or
  /// the blob isn't version 1 of the right length.
  static func openRecovery(blob: Data, code: String) throws -> Data {
    guard blob.count == 1 + 16 + 12 + 32 + 16, blob.first == 0x01 else { throw Failure.badWire }
    let bytes = Data(blob)  // re-based, so the offsets below start at zero
    let salt = bytes.subdata(in: 1..<17), nonce = bytes.subdata(in: 17..<29)
    let box = try AES.GCM.SealedBox(nonce: try AES.GCM.Nonce(data: nonce), ciphertext: bytes.subdata(in: 29..<61), tag: bytes.subdata(in: 61..<77))
    return try AES.GCM.open(box, using: SymmetricKey(data: try recoveryKey(code: code, salt: salt)))
  }

  /// Six digits both phones show when a new phone asks for the key: each works them out from the new phone's own key (the one the share is wrapped
  /// to, SPKI base64url) and the approval request's id. The athlete compares them, since the
  /// name alone is "iPhone" on every phone. The first four bytes of the SHA-256, as a number,
  /// modulo a million.
  ///
  /// What it covers: a phone someone else signed in on with an intercepted emailed code shows a
  /// code the athlete has no phone to match. What it doesn't: a server that swaps the key can
  /// try keys until one gives the same six digits; closing that needs a commitment step
  /// (RFC 6189), which is not built.
  static func compareCode(key: String, requestId: String) -> String {
    let digest = SHA256.hash(data: Data("leave:v1:device-compare:\(requestId):\(key)".utf8))
    let number = digest.prefix(4).reduce(UInt32(0)) { ($0 << 8) | UInt32($1) }
    return String(format: "%06u", number % 1_000_000)
  }

  static func base64url(_ data: Data) -> String {
    data.base64EncodedString().replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_").replacingOccurrences(of: "=", with: "")
  }

  static func fromBase64url(_ s: String) -> Data? {
    var b = s.replacingOccurrences(of: "-", with: "+").replacingOccurrences(of: "_", with: "/")
    while b.count % 4 != 0 { b.append("=") }
    return Data(base64Encoded: b)
  }

  // MARK: - ASN.1 helpers: Security wants PKCS#1 for RSA keys, the API sends SPKI / PKCS#8

  /// SPKI DER → PKCS#1 RSAPublicKey by unwrapping the outer SEQUENCE { AlgorithmIdentifier, BIT STRING }.
  static func stripSpkiHeaderIfRSA(_ der: Data) -> Data {
    guard let outer = asn1Sequence(der), let (_, afterAlg) = asn1Element(outer, at: 0), let (bits, _) = asn1Element(outer, at: afterAlg) else { return der }
    // bits = BIT STRING contents: first byte is the unused-bits count.
    return bits.count > 1 ? bits.dropFirst() : der
  }

  /// PKCS#8 DER → PKCS#1 RSAPrivateKey (the OCTET STRING after version and AlgorithmIdentifier).
  static func stripPkcs8HeaderIfRSA(_ der: Data) -> Data {
    guard let outer = asn1Sequence(der),
          let (_, afterVersion) = asn1Element(outer, at: 0),
          let (_, afterAlg) = asn1Element(outer, at: afterVersion),
          let (octets, _) = asn1Element(outer, at: afterAlg) else { return der }
    return octets
  }

  private static func asn1Sequence(_ der: Data) -> Data? {
    guard let (content, _) = asn1Element(der, at: 0), der.first == 0x30 else { return nil }
    return content
  }

  /// Returns the content of the TLV starting at `offset` and the offset just past it.
  private static func asn1Element(_ d: Data, at offset: Int) -> (Data, Int)? {
    let bytes = [UInt8](d)
    guard offset + 1 < bytes.count else { return nil }
    var i = offset + 1
    var length = Int(bytes[i])
    i += 1
    if length & 0x80 != 0 {
      let n = length & 0x7f
      guard i + n <= bytes.count else { return nil }
      length = 0
      for _ in 0..<n { length = (length << 8) | Int(bytes[i]); i += 1 }
    }
    guard i + length <= bytes.count else { return nil }
    return (Data(bytes[i..<(i + length)]), i + length)
  }
}
